<template><view class="state"><view class="state-icon">{{ icon }}</view><text class="title">{{ title }}</text><text class="description">{{ description }}</text><view v-if="actionText" class="action" @click="$emit('action')">{{ actionText }}</view></view></template>
<script setup>defineProps({icon:{type:String,default:'杯'},title:{type:String,default:'暂无内容'},description:{type:String,default:'稍后再来看看'},actionText:{type:String,default:''}});defineEmits(['action'])</script>
<style lang="scss" scoped>.state{padding:96rpx 40rpx;text-align:center}.state-icon{width:104rpx;height:104rpx;margin:0 auto 24rpx;display:flex;align-items:center;justify-content:center;border-radius:50%;background:$cozy-surface;color:$cozy-primary;font-weight:750}.title{display:block;color:$cozy-ink;font-size:30rpx;font-weight:700}.description{display:block;margin-top:12rpx;color:$cozy-muted;font-size:24rpx;line-height:1.5}.action{min-width:200rpx;height:80rpx;margin:30rpx auto 0;display:inline-flex;align-items:center;justify-content:center;border-radius:$cozy-radius-md;background:$cozy-primary;color:#fff;font-size:25rpx;font-weight:650}</style>
